use vstd::prelude::*;

verus! {

    // Specification for the reverse function
    fn reverse(s: Vec<i8>) -> (rev: Vec<i8>)
        requires
            // The input vector can be of any length, including zero
            true,
        ensures
            // The output vector has the same length as the input vector
            rev.len() == s.len() &&
            // For every valid index k, the element at position k in the result
            // equals the element at position n - 1 - k in the input
            forall|k: nat| (k < s.len() as nat) ==> (rev[k] == s[(s.len() as nat - 1 - k)])
    {
        let mut rev: Vec<i8> = Vec::new();
        let n = s.len() as nat;

        // Initialize the output vector with the same length as the input
        rev.resize(n as usize, 0);

        // Fill the output vector in reverse order
        let mut i: nat = 0;
        while i < n
            invariant
                i <= n,
                rev.len() == s.len(),
                forall|k: nat| (k < i) ==> (rev[k] == s[(n - 1 - k)]) // Invariant for filled elements
            , 
            decreases n - i,
        {
            rev[i as usize] = s[(n - 1 - i) as usize]; // Fill the current index
            i = i + 1; // Move to the next index
        }

        rev // Return the reversed vector
    }
}

